// Parse and structure the AI response
const aiResponse = $input.first().json.message.content;

try {
  // Extract structured data from AI response
  const questionData = {
    id: Date.now(),
    question: extractSection(aiResponse, 'Question:'),
    difficulty: $('Webhook Trigger').first().json.body.difficulty || 'beginner',
    concept: extractSection(aiResponse, 'Concept:'),
    schema: extractSection(aiResponse, 'Schema:'),
    expectedQuery: extractSection(aiResponse, 'Query:'),
    explanation: extractSection(aiResponse, 'Explanation:'),
    visualHints: extractSection(aiResponse, 'Visual:'),
    commonMistakes: extractSection(aiResponse, 'Mistakes:'),
    timestamp: new Date().toISOString()
  };

  // Generate visual example data
  questionData.sampleData = generateSampleData(questionData.schema);

  return [questionData];
} catch (error) {
  return [{
    error: true,
    message: 'Failed to process question generation',
    details: error.message
  }];
}

function extractSection(text, marker) {
  const lines = text.split('\n');
  const startIndex = lines.findIndex(line => line.includes(marker));
  if (startIndex === -1) return '';

  const result = [];
  for (let i = startIndex + 1; i < lines.length; i++) {
    if (lines[i].match(/^\d+\.|^[A-Z][a-z]+:/)) break;
    if (lines[i].trim()) result.push(lines[i]);
  }
  return result.join('\n').trim();
}

function generateSampleData(schema) {
  // Generate sample data based on schema description
  return {
    tables: [
      {
        name: 'employees',
        columns: ['id', 'name', 'department', 'salary'],
        data: [
          [1, 'John Doe', 'Engineering', 75000],
          [2, 'Jane Smith', 'Marketing', 65000],
          [3, 'Mike Johnson', 'Engineering', 80000]
        ]
      }
    ]
  };
}

