// Process answer evaluation and generate response
const evaluation = $input.first().json.message.content;
const originalData = $('Webhook Trigger').first().json.body;

const result = {
  correct: evaluation.toLowerCase().includes('correct') || evaluation.toLowerCase().includes('good'),
  feedback: evaluation,
  score: calculateScore(evaluation),
  nextSuggestion: generateNextSuggestion(originalData.difficulty),
  timestamp: new Date().toISOString()
};

return [result];

function calculateScore(feedback) {
  // Simple scoring algorithm based on feedback keywords
  let score = 50; // Base score

  if (feedback.toLowerCase().includes('correct')) score += 30;
  if (feedback.toLowerCase().includes('excellent')) score += 20;
  if (feedback.toLowerCase().includes('good')) score += 15;
  if (feedback.toLowerCase().includes('syntax error')) score -= 20;
  if (feedback.toLowerCase().includes('incorrect')) score -= 25;

  return Math.max(0, Math.min(100, score));
}

function generateNextSuggestion(currentDifficulty) {
  const suggestions = {
    beginner: ['Try an intermediate JOIN question', 'Practice GROUP BY clauses'],
    intermediate: ['Explore subqueries', 'Advanced filtering with HAVING'],
    advanced: ['Window functions', 'Complex CTEs and recursive queries']
  };

  const options = suggestions[currentDifficulty] || suggestions.beginner;
  return options[Math.floor(Math.random() * options.length)];
}

// Generate visual representations for SQL concepts
const requestData = $('Webhook Trigger').first().json.body;

const visual = {
  type: 'sql_visualization',
  concept: requestData.concept,
  tableStructure: generateTableHTML(requestData.sampleData),
  queryFlow: generateQueryFlowDiagram(requestData.query),
  resultPreview: generateResultHTML(requestData.expectedResult),
  interactiveElements: generateInteractiveCode(requestData.query)
};

return [visual];

function generateTableHTML(sampleData) {
  if (!sampleData || !sampleData.tables) return '<p>No sample data available</p>';

  let html = '';
  sampleData.tables.forEach(table => {
    html += `<div class="table-container">
      <h3>${table.name}</h3>
      <table class="sql-table">
        <thead><tr>`;

    table.columns.forEach(col => {
      html += `<th>${col}</th>`;
    });

    html += `</tr></thead><tbody>`;

    table.data.forEach(row => {
      html += '<tr>';
      row.forEach(cell => {
        html += `<td>${cell}</td>`;
      });
      html += '</tr>';
    });

    html += '</tbody></table></div>';
  });

  return html;
}

function generateQueryFlowDiagram(query) {
  // Create a simple flow diagram representation
  return {
    steps: [
      { step: 1, action: 'FROM clause - Select source table(s)' },
      { step: 2, action: 'WHERE clause - Filter rows' },
      { step: 3, action: 'GROUP BY - Group similar rows' },
      { step: 4, action: 'HAVING - Filter groups' },
      { step: 5, action: 'SELECT - Choose columns' },
      { step: 6, action: 'ORDER BY - Sort results' }
    ]
  };
}

function generateResultHTML(result) {
  return '<div class="result-preview"><p>Expected result will be displayed here</p></div>';
}

function generateInteractiveCode(query) {
  return {
    editable: true,
    syntax_highlighting: true,
    auto_complete: true,
    query: query || 'SELECT * FROM table_name;'
  };
}
